import{_ as p,C as r,o as i,c as l,j as o,a as t,E as d,ah as c}from"./chunks/framework.BpF7DVZ1.js";const q=JSON.parse('{"title":"排印","description":"","frontmatter":{},"headers":[],"relativePath":"components/typography.md","filePath":"components/typography.md","lastUpdated":1788635489000}'),n={name:"components/typography.md"},s={id:"排印",tabindex:"-1"};function y(g,e,x,u,b,f){const h=r("Badge"),a=r("XhDemo");return i(),l("div",null,[o("h1",s,[e[0]||(e[0]=t("排印 ",-1)),d(h,{type:"info",text:"typography"}),e[1]||(e[1]=t()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#排印","aria-label":'Permalink to "排印 <Badge type="info" text="typography" />"'},"​",-1))]),e[3]||(e[3]=c('<p>一块正文的排版容器：管住段间距与最大行宽，标题、段落与行内文字各自拿自己的字号、字重与行高。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>渲染一段较长的正文：文章、说明、条款、AI 回复。</li><li>需要标题层级与段落节奏一致，而不想逐处写字号。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是一行标签或一句提示：直接写文本，别套整套排版。</li><li>要把长文本裁成几行：用<a href="./truncate">文本截断</a>。</li><li>要渲染 Markdown：用 <code>@xihan-ui/markdown</code>，它产出的节点套一层 <code>prose</code> 部件即得排版。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>root</code> 管段间距与最大行宽；<code>level</code> 只换标题字号档位，用哪个标签由作者定。</li><li>行内文字三种形态：<code>muted</code> 弱化、<code>strong</code> 加重、<code>code</code> 等宽；与语气、字重是三条轴，可以一起写。</li><li><code>link</code> 是一个独立部件，链接样式不必另写。</li><li><code>prose</code> 收外来的整段 HTML：节点由内容自己带，标题、段落、列表、代码块、引用、表格按标签上样式。</li><li><code>align</code> 与 <code>weight</code> 落在 <code>root</code> 上，整块正文一起换；<code>weight</code> 也能只写在一段行内文字上。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root 管段间距与最大行宽，标题与段落各自拿字号、字重、行高</p>',10)),d(a,{src:"typography/01-basic"}),e[4]||(e[4]=o("h3",{id:"标题档位",tabindex:"-1"},[t("标题档位 "),o("a",{class:"header-anchor",href:"#标题档位","aria-label":'Permalink to "标题档位"'},"​")],-1)),e[5]||(e[5]=o("p",null,"level 只换字号档位，用哪个标签由作者定；不传 level 即默认档",-1)),d(a,{src:"typography/02-heading-level"}),e[6]||(e[6]=o("h3",{id:"行内文字",tabindex:"-1"},[t("行内文字 "),o("a",{class:"header-anchor",href:"#行内文字","aria-label":'Permalink to "行内文字"'},"​")],-1)),e[7]||(e[7]=o("p",null,"variant 换形态：muted 弱化、strong 加重、code 等宽",-1)),d(a,{src:"typography/03-text"}),e[8]||(e[8]=o("h3",{id:"语气",tabindex:"-1"},[t("语气 "),o("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),e[9]||(e[9]=o("p",null,"tone 决定这一段行内文字用哪族颜色，与 variant 是两个轴，可以一起写",-1)),d(a,{src:"typography/04-tone"}),e[10]||(e[10]=o("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),o("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),e[11]||(e[11]=o("p",null,"size 换的是整块正文的字号与段间距，不传 size 即默认档",-1)),d(a,{src:"typography/05-size"}),e[12]||(e[12]=o("h3",{id:"富文本",tabindex:"-1"},[t("富文本 "),o("a",{class:"header-anchor",href:"#富文本","aria-label":'Permalink to "富文本"'},"​")],-1)),e[13]||(e[13]=o("p",null,"prose 收外来的整段 HTML：节点由内容自己带，样式按标签给",-1)),d(a,{src:"typography/06-prose"}),e[14]||(e[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-typography&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTypographyHeading</code> <code>XhTypographyLink</code> <code>XhTypographyParagraph</code> <code>XhTypographyProse</code> <code>XhTypographyRoot</code> <code>XhTypographyText</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/typography.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;typography&quot;</code>：<strong><code>root</code></strong> · <code>heading</code> · <code>paragraph</code> · <code>text</code> · <code>link</code> · <code>prose</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>align</code></td><td><code>TypographyAlign</code></td><td></td><td>对齐：start / center / end / justify，整块正文跟着换。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，整块正文的字号与段间距跟着换档。</td></tr><tr><td><code>weight</code></td><td><code>TypographyWeight</code></td><td></td><td>字重：regular / medium / semibold / bold，整块正文跟着换。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeadingProps</code></td><td><code>(props?: TypographyHeadingProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getParagraphProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTextProps</code></td><td><code>(props?: TypographyTextProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLinkProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getProseProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>富文本容器：外来的 HTML（Markdown 渲染结果）铺进来，样式按标签给。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/typography.css</code> 按部件选择：<code>[data-scope=&quot;typography&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-align</code></td><td>props.align</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-weight</code></td><td>props.weight</td></tr><tr><td><code>heading</code></td><td><code>data-level</code></td><td>levelAttr(heading.level)</td></tr><tr><td><code>text</code></td><td><code>data-tone</code></td><td>text.tone</td></tr><tr><td><code>text</code></td><td><code>data-variant</code></td><td>text.variant</td></tr><tr><td><code>text</code></td><td><code>data-weight</code></td><td>text.weight</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-typography-block-gap</code> · <code>--xh-typography-code-bg</code> · <code>--xh-typography-code-font</code> · <code>--xh-typography-code-font-size</code> · <code>--xh-typography-code-px</code> · <code>--xh-typography-code-py</code> · <code>--xh-typography-code-radius</code> · <code>--xh-typography-fg</code> · <code>--xh-typography-font-size</code> · <code>--xh-typography-font-weight</code> · <code>--xh-typography-heading-fg</code> · <code>--xh-typography-heading-font-size</code> · <code>--xh-typography-heading-font-weight</code> · <code>--xh-typography-heading-gap</code> · <code>--xh-typography-heading-leading</code> · <code>--xh-typography-leading</code> · <code>--xh-typography-link-fg</code> · <code>--xh-typography-link-fg-hover</code> · <code>--xh-typography-link-radius</code> · <code>--xh-typography-link-underline-offset</code> · <code>--xh-typography-measure</code> · <code>--xh-typography-prose-block-gap</code> · <code>--xh-typography-prose-cell-border</code> · <code>--xh-typography-prose-cell-px</code> · <code>--xh-typography-prose-cell-py</code> · <code>--xh-typography-prose-fg</code> · <code>--xh-typography-prose-font-size</code> · <code>--xh-typography-prose-h1</code> · <code>--xh-typography-prose-h2</code> · <code>--xh-typography-prose-h3</code> · <code>--xh-typography-prose-h4</code> · <code>--xh-typography-prose-h5</code> · <code>--xh-typography-prose-h6</code> · <code>--xh-typography-prose-heading-fg</code> · <code>--xh-typography-prose-heading-font-weight</code> · <code>--xh-typography-prose-heading-gap</code> · <code>--xh-typography-prose-item-gap</code> · <code>--xh-typography-prose-leading</code> · <code>--xh-typography-prose-link-fg</code> · <code>--xh-typography-prose-link-radius</code> · <code>--xh-typography-prose-list-ps</code> · <code>--xh-typography-prose-pre-bg</code> · <code>--xh-typography-prose-pre-padding</code> · <code>--xh-typography-prose-pre-radius</code> · <code>--xh-typography-prose-quote-border</code> · <code>--xh-typography-prose-quote-fg</code> · <code>--xh-typography-prose-quote-ps</code> · <code>--xh-typography-prose-rule-border</code> · <code>--xh-typography-prose-strong-font-weight</code> · <code>--xh-typography-prose-th-font-weight</code> · <code>--xh-typography-text-fg-muted</code> · <code>--xh-typography-text-fg-tone</code> · <code>--xh-typography-text-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>hover: hover</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./highlight">文本高亮</a>配合做检索命中标记；与<a href="./code-view">代码视图</a>配合放整段代码。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>最大行宽交给 <code>root</code>，别让正文横贯整个宽屏——一行超过约四十个汉字就很难回到下一行的行首。</li><li>标题层级按文档结构选标签，视觉大小用 <code>level</code> 单独调，两件事分开。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>为了字大就用 <code>&lt;h1&gt;</code>：读屏用户按标题跳转时会撞见错的结构。</li><li>在正文块里塞交互控件却不留间距，点击目标会挤在一起。</li></ul>',34))])}const P=p(n,[["render",y]]);export{q as __pageData,P as default};
